import * as THREE from 'three';
import {VIEWS} from './config.js';
export function bindControls(camera,controls,renderer,picks,tags){let destination=null;const ray=new THREE.Raycaster(),mouse=new THREE.Vector2();let start;
 renderer.domElement.addEventListener('pointerdown',event=>start=[event.clientX,event.clientY]);renderer.domElement.addEventListener('pointerup',event=>{if(!start||Math.hypot(event.clientX-start[0],event.clientY-start[1])>6)return;mouse.set(event.clientX/innerWidth*2-1,1-event.clientY/innerHeight*2);ray.setFromCamera(mouse,camera);const hit=ray.intersectObjects(picks)[0];const info=document.getElementById('info');info.classList.toggle('show',!!hit);if(hit)document.getElementById('cabName').textContent=hit.object.userData.name});document.getElementById('close').onclick=()=>document.getElementById('info').classList.remove('show');
 const view=name=>{destination=new THREE.Vector3(...VIEWS[name]);document.querySelectorAll('[data-view]').forEach(button=>button.classList.toggle('active',button.dataset.view===name))};document.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>view(button.dataset.view));document.getElementById('reset').onclick=()=>{view('iso');document.getElementById('info').classList.remove('show')};document.getElementById('tags').onclick=event=>{const visible=!tags[0].visible;tags.forEach(tag=>tag.visible=visible);event.currentTarget.classList.toggle('active',visible)};
 addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});return ()=>{if(destination){camera.position.lerp(destination,.09);if(camera.position.distanceTo(destination)<.03)destination=null}controls.update()};
}
